[
  {
    "slot_number": "slot-3-1-2",
    "slot_key": "Preconditions before issuing a lane reversal command",
    "slot_value": "Operators need a clear, current picture of lane status, field devices, and whether anything is preventing the change before issuing a command; the system should also warn when the system or field devices are not in the right state and show enough context to explain why an action cannot proceed. They should only be able to open or close the lane when the system confirms the field devices are in a safe and expected state, when the relevant operational configuration for that period is active, and when there is no conflict, fault, or incomplete transition; otherwise the operator should be blocked or clearly warned before proceeding. The command should be rejected or delayed if the lane configuration does not match the allowed time window, if another control sequence is already in progress, if the system cannot confirm the devices are synchronized closely enough to proceed safely, or if there is a communications issue that makes status uncertain. The system should force a warning acknowledgment when the action changes lane direction, affects a peak-period transition, or is being done under degraded conditions.",
    "operation": "refine"
  },
  {
    "slot_number": "slot-3-1-dyn-4",
    "slot_key": "Critical command confirmation safeguard",
    "slot_value": "Require explicit, deliberate, and obvious operator confirmation before a critical command is executed; warning acknowledgment is specifically required when the action changes lane direction, affects a peak-period transition, or is being done under degraded conditions.",
    "operation": "refine"
  }
]

[
  {
    "slot_number": "slot-6-1-1",
    "slot_key": "Mandatory business rules for lane activation and deactivation",
    "slot_value": "Operators may open or close the reversible lane only when the system confirms the field devices are in a safe and expected state and the relevant operational configuration for that period is active. If there is any conflict, fault, or incomplete transition, the operator must be blocked or clearly warned before proceeding. Proper authorization is also required so only approved traffic operators can issue the commands. The command should be rejected or delayed if the lane configuration does not match the allowed time window, if another control sequence is already in progress, if the system cannot confirm the devices are synchronized closely enough to proceed safely, or if communications issues make the status uncertain.",
    "operation": "refine"
  },
  {
    "slot_number": "slot-6-1-3",
    "slot_key": "Approval conditions required before changing lane direction",
    "slot_value": "In normal day-to-day operations, operators should be able to issue lane open or close commands without waiting for separate supervisor approval as long as they are authorized and the system conditions are satisfied. Supervisor involvement is more likely for exceptions, unusual event operations, or when a system issue requires manual judgment. No formal approval workflow is known to be required for every command; if one exists in certain situations, it must be clearly defined and support exception handling and the district's audit trail requirements. The system should force a warning acknowledgment before proceeding when the action changes the lane direction, affects a peak-period transition, or is being done under degraded conditions.",
    "operation": "refine"
  }
]

[
  {
    "slot_number": "slot-8-1-3",
    "slot_key": "Backup or fail-safe behavior during system degradation",
    "slot_value": "Safer coordination with other transportation systems and authorized users, with better operational visibility and reporting during degraded or difficult-to-obtain information conditions. Acceptance also requires that authorized users and approved partner systems can receive the right operational data under controlled access, and that the system works in normal and abnormal scenarios without workarounds. Full rollback is required if there is any doubt about command integrity, field-device synchronization, or operator visibility, especially during an active traffic period, with a clean return to the last known safe state before further changes. The system should delay commands when communications issues make status uncertain, and should force explicit warning acknowledgment before proceeding when changing lane direction, during peak-period transitions, or under degraded conditions.",
    "operation": "refine"
  }
]

[
  {
    "slot_number": "slot-8-2-dyn-4",
    "slot_key": "Safe-state and active-configuration preconditions for reversible lane commands",
    "slot_value": "The system must confirm that field devices are in a safe and expected state and that the relevant operational configuration or schedule/mode for that period is active before an operator can open or close a reversible lane. It should also verify that current status feedback is available so the command can be tracked and confirmed, and it should reject or delay the command if the lane configuration does not match the allowed time window, if another control sequence is already in progress, if the devices cannot be confirmed as synchronized closely enough to proceed safely, or if communications issues make status uncertain.",
    "operation": "refine"
  },
  {
    "slot_number": "slot-8-2-dyn-5",
    "slot_key": "Conflict or incomplete-transition blocking and warning for lane commands",
    "slot_value": "If there is any conflict, fault, incomplete prior transition, or unsafe traffic-control state, the operator should be blocked or at least warned clearly before proceeding with an open/close command. In some cases, the operator may be allowed to proceed only after acknowledging the warning and confirming they understand the risk. Shared lane state labels should clearly distinguish open, closed, and in transition, with the transition state indicating the system is changing but not yet fully in the final condition. The replacement should avoid ambiguous terms and make boundaries very clear, especially around partial activation, commanded state versus confirmed field state, and any fault condition. The system should force a warning acknowledgment when the action changes lane direction, affects a peak-period transition, or is being done under degraded conditions.",
    "operation": "refine"
  }
]

